MOD3_ORIG = [
  dict(q="Một cổng logic chuẩn sản xuất năm 1981 nhiều khả năng được đóng gói dạng:", en="A standard logic gate manufactured in 1981 is likely to be supplied in a:",
       opts=["gói DIL","gói PGA","gói QFP"], correct=0, src="Tooley Ch.8 Q1",
       explain="Thập niên 1980, DIL (Dual-In-Line) là kiểu đóng gói phổ biến nhất cho IC logic chuẩn.", detail='<p>Trước khi công nghệ dán bề mặt (surface-mount) trở nên phổ biến từ cuối thập niên 1980, hầu như mọi IC logic tiêu chuẩn đều dùng gói DIL (Dual-In-Line) với hai hàng chân cắm xuyên lỗ, dễ hàn tay và dễ cắm vào đế socket để thay thế khi cần sửa chữa.</p>', detail_en='<p>Before surface-mount technology became widespread in the late 1980s, almost every standard logic IC used a DIL (Dual-In-Line) package with two rows of through-hole pins, which was easy to hand-solder and easy to plug into a socket for repair.</p>'),
  dict(q="Một cổng logic chuẩn (standard logic gate) là ví dụ điển hình của loại tích hợp nào?", en="A standard logic gate is a typical example of:",
       opts=["thiết bị SSI","thiết bị LSI","thiết bị VLSI"], correct=0, src="Tooley Ch.8 Q2",
       explain="Cổng logic đơn lẻ chỉ chứa vài transistor → thuộc quy mô tích hợp nhỏ SSI.", detail='<p>Quy mô tích hợp (scale of integration) được phân loại theo số lượng cổng logic tương đương nằm trong một chip: SSI (Small Scale Integration) chỉ có vài cổng đơn lẻ, MSI (Medium) có vài chục tới khoảng trăm cổng, LSI (Large) lên tới hàng nghìn, còn VLSI (Very Large) chứa hàng triệu transistor trở lên như trong vi xử lý hiện đại.</p>', detail_en='<p>Scale of integration is classified by the number of equivalent logic gates on one chip: SSI (Small Scale Integration) holds only a handful of individual gates, MSI (Medium) holds tens to around a hundred gates, LSI (Large) reaches into the thousands, and VLSI (Very Large) contains millions of transistors or more, as in a modern microprocessor.</p>'),
  dict(q="Trong các mức độ tích hợp sau, mức nào có mật độ transistor LỚN HƠN?", en="Which one of the following scales of integration is the largest:",
       opts=["SSI","LSI","MSI"], correct=1, src="Tooley Ch.8 Q3",
       explain="Thứ tự tăng dần mật độ: SSI < MSI < LSI < VLSI; trong 3 lựa chọn, LSI lớn nhất.", detail="<p>Bốn mức quy mô tích hợp luôn được xếp theo đúng thứ tự SSI, MSI, LSI, VLSI từ ít tới nhiều cổng logic nhất. Ghi nhớ đúng thứ tự này giúp trả lời nhanh mọi câu hỏi so sánh 'mức nào lớn hơn' mà không cần nhớ số cổng chính xác của từng mức.</p>", detail_en="<p>The four integration scales always follow the fixed order SSI, MSI, LSI, VLSI, from fewest to most logic gates. Remembering this order makes it quick to answer any 'which scale is larger' question without needing to recall the exact gate count of each level.</p>"),
  dict(q="Vi xử lý (microprocessor) là ví dụ của công nghệ:", en="A microprocessor is an example of:",
       opts=["công nghệ SSI","công nghệ MSI","công nghệ VLSI"], correct=2, src="Tooley Ch.8 Q4",
       explain="Vi xử lý chứa hàng triệu transistor → thuộc quy mô tích hợp rất lớn VLSI.", detail='<p>Một vi xử lý hiện đại tích hợp từ vài triệu tới hàng tỉ transistor trên một chip duy nhất, vượt xa ngưỡng vài nghìn cổng của LSI, nên luôn được xếp vào VLSI (Very Large Scale Integration). Đây cũng là công nghệ cho phép thu nhỏ toàn bộ đơn vị xử lý trung tâm của một máy tính vào một con chip duy nhất thay vì cả một bo mạch lớn như thời kỳ đầu.</p>', detail_en='<p>A modern microprocessor packs anywhere from several million to billions of transistors onto a single chip, far beyond the few thousand gates typical of LSI, so it is always classed as VLSI (Very Large Scale Integration). This is exactly the technology that allows an entire central processing unit to shrink onto one chip instead of filling a large circuit board as in early computers.</p>'),
  dict(q="So với đóng gói DIP, đóng gói PLCC mang lại ưu điểm nào?", en="Compared with DIP packaging, PLCC offers:",
       opts=["nhiều chân hơn trên cùng kích thước","kích thước lớn hơn","độ tin cậy cao hơn"], correct=0, src="Tooley Ch.8 Q5",
       explain="PLCC (Plastic Leaded Chip Carrier) cho phép bố trí nhiều chân hơn trong diện tích nhỏ gọn hơn so với DIP.", detail='<p>PLCC bố trí chân theo cả bốn cạnh của gói vuông thay vì chỉ hai hàng như DIP, nên với cùng một diện tích đế, PLCC chứa được nhiều chân hơn hẳn. Đánh đổi là PLCC khó hàn tay hơn và thường cần đế cắm chuyên dụng hoặc máy hàn dán bề mặt.</p>', detail_en='<p>PLCC places pins along all four sides of a square package instead of just two rows as in DIP, so for the same footprint area it fits considerably more pins. The trade-off is that PLCC is harder to hand-solder and usually needs a dedicated socket or surface-mount soldering equipment.</p>'),
  dict(q="Kiểu đóng gói IC nào bắt buộc phải hàn cố định (không thể cắm vào đế/socket)?", en="Which IC packaging technology requires the chip to always be soldered in place:",
       opts=["DIL","SOIC","PGA"], correct=1, src="Tooley Ch.8 Q6",
       explain="SOIC là gói dán bề mặt (surface-mount), luôn được hàn trực tiếp lên board, không dùng đế cắm như DIL/PGA.", detail='<p>SOIC (Small Outline IC) thuộc họ gói dán bề mặt (surface-mount), với chân dạng gull-wing hàn trực tiếp lên lớp đồng của board mạch in, không có phiên bản đế cắm rời như DIL hay PGA. Đặc điểm này giúp SOIC nhỏ gọn hơn nhiều nhưng cũng khó tháo lắp lại hơn khi sửa chữa.</p>', detail_en='<p>SOIC (Small Outline IC) belongs to the surface-mount package family, with gull-wing leads soldered directly onto the copper pads of the printed circuit board, with no separate socketed version the way DIL or PGA have. This makes SOIC considerably more compact but also harder to remove and re-seat during repair.</p>'),
  dict(q="Công nghệ đóng gói IC nào ra đời SỚM NHẤT trong các lựa chọn sau?", en="Which of the following IC packaging technologies was the earliest to be used:",
       opts=["ceramic DIP","ceramic QFP","PLCC"], correct=0, src="Tooley Ch.8 Q7",
       explain="Ceramic DIP là kiểu đóng gói IC thương mại sớm nhất trong ba lựa chọn.", detail='<p>Trong lịch sử đóng gói IC, ceramic DIP xuất hiện từ những năm 1960, sớm hơn nhiều so với plastic DIP (rẻ hơn, ra đời sau) và các gói bề mặt như QFP hay PLCC vốn chỉ phổ biến từ cuối thập niên 1970 trở đi khi nhu cầu thu nhỏ mật độ linh kiện tăng lên.</p>', detail_en='<p>In the history of IC packaging, ceramic DIP dates back to the 1960s, well before the cheaper plastic DIP that followed it and before surface-mount packages such as QFP or PLCC, which only became common from the late 1970s onward as the demand for higher component density grew.</p>'),
  dict(q="Các mối nối từ pad trên die IC tới chân ra thường được:", en="The connections from the pads on an integrated circuit die are:",
       opts=["hàn thiếc vào dây nối trong","bấm (crimp) vào dây nối trong","hàn siêu âm/nhiệt (welded) vào dây nối trong"], correct=2, src="Tooley Ch.8 Q8",
       explain="Kỹ thuật wire-bonding gắn dây vàng/nhôm từ pad tới khung dẫn bằng hàn siêu âm/nhiệt (welded), không phải hàn thiếc thông thường.", detail='<p>Wire-bonding dùng một sợi dây vàng hoặc nhôm rất mảnh, gắn từng đầu dây vào pad trên die và vào khung dẫn (lead frame) bằng nhiệt kết hợp áp lực và sóng siêu âm, tạo ra một mối hàn khuếch tán kim loại thực sự chứ không phải lớp thiếc hàn phủ lên như kỹ thuật hàn thông thường trên board mạch.</p>', detail_en='<p>Wire-bonding uses an extremely thin gold or aluminium wire, with each end attached to a pad on the die and to the lead frame using heat combined with pressure and ultrasonic energy, forming a true metal-diffusion weld rather than a layer of solder the way ordinary board-level soldering works.</p>'),
  dict(q="Một IC bus transceiver chứa 64 cổng logic và bộ đệm. Chip này là ví dụ của quy mô tích hợp:", en="An IC bus transceiver containing 64 logic gates and buffers is an example of:",
       opts=["SSI","MSI","LSI"], correct=1, src="Tooley Ch.8 Q9",
       explain="Vài chục tới ~100 cổng logic tương ứng quy mô tích hợp vừa MSI.", detail='<p>64 cổng logic nằm gọn trong khoảng vài chục tới một trăm cổng, đúng ngưỡng phân loại MSI (Medium Scale Integration), cao hơn hẳn một cổng logic đơn lẻ (SSI) nhưng còn thấp hơn nhiều so với hàng nghìn cổng của LSI.</p>', detail_en='<p>64 logic gates sit comfortably within the tens-to-around-a-hundred gate range that defines MSI (Medium Scale Integration), well above a single standalone gate (SSI) but far below the thousands of gates found in LSI.</p>'),
  dict(q="Việc kiểm tra sản xuất (production test) trên một wafer IC được thực hiện:", en="Production tests are performed on an integrated circuit wafer:",
       opts=["trước khi cắt thành từng chip riêng","sau khi cắt thành từng chip riêng","chỉ khi chip đã được gắn lên board"], correct=0, src="Tooley Ch.8 Q13",
       explain="Wafer được kiểm tra (wafer probing) ngay khi còn nguyên tấm, trước công đoạn cắt (dicing).", detail='<p>Kiểm tra khi wafer còn nguyên tấm (wafer probing) cho phép loại bỏ ngay những die lỗi bằng đầu dò điện tự động, tránh lãng phí công đoạn đóng gói tốn kém cho những chip vốn đã hỏng ngay từ khâu chế tạo. Việc cắt (dicing) chỉ diễn ra sau khi đã đánh dấu rõ die nào đạt, die nào không đạt.</p>', detail_en='<p>Testing while the wafer is still intact (wafer probing) lets defective die be identified immediately with automated electrical probes, avoiding the costly packaging step for chips that were already faulty at the fabrication stage. Dicing only happens after the good and bad die have been clearly marked.</p>'),
  dict(q="Mỗi mạch tích hợp riêng lẻ được cắt ra từ một wafer được gọi là:", en="Each individual integrated circuit produced from a wafer is known as a:",
       opts=["blank","die","gate"], correct=1, src="Tooley Ch.8 Q15",
       explain="Thuật ngữ chuẩn cho một chip cắt rời từ wafer là 'die'.", detail="<p>Một wafer bán dẫn chứa hàng trăm tới hàng nghìn bản sao của cùng một mạch, mỗi bản sao riêng lẻ sau khi cắt ra được gọi là một 'die' (số nhiều là 'dice' hoặc 'dies'). Chỉ sau khi đóng gói (packaging) die đó vào vỏ nhựa hoặc gốm cùng khung chân, sản phẩm mới được gọi là một IC hoàn chỉnh.</p>", detail_en="<p>A semiconductor wafer holds hundreds to thousands of copies of the same circuit; each individual copy, once cut out, is called a 'die' (plural 'dice' or 'dies'). Only after that die is packaged into a plastic or ceramic case with a lead frame does the product become a finished IC.</p>"),
  dict(q="Fan-out của một cổng logic TTL chuẩn là:", en="A standard TTL logic gate has a fan-out of:",
       opts=["5","10","20"], correct=1, src="Tooley Ch.9 Q1",
       explain="TTL chuẩn có fan-out danh định là 10 (điều khiển được tối đa 10 đầu vào TTL cùng họ).", detail='<p>Fan-out giới hạn số đầu vào cùng họ logic mà một đầu ra có thể điều khiển an toàn, vì mỗi đầu vào rút một lượng dòng nhỏ từ đầu ra đó. Vượt quá 10 đầu vào TTL trên một đầu ra TTL chuẩn có thể khiến điện áp mức cao tụt xuống dưới ngưỡng nhận biết logic 1 của các cổng phía sau, gây lỗi logic ngẫu nhiên khó phát hiện.</p>', detail_en='<p>Fan-out limits how many same-family logic inputs a single output can safely drive, since each input draws a small amount of current from that output. Exceeding 10 TTL inputs on one standard TTL output can pull the high-level voltage below the logic-1 recognition threshold of the following gates, causing intermittent logic errors that are hard to trace.</p>'),
  dict(q="Số lượng tải đầu vào chuẩn (cùng họ logic) mà MỘT đầu vào của mạch logic tạo ra được gọi là:", en="The equivalent number of standard input loads imposed by the input of a logic circuit is known as:",
       opts=["fan-in","fan-out","fan-load"], correct=0, src="Tooley Ch.9 Q2",
       explain="Đây chính là định nghĩa của fan-in.", detail='<p>Fan-in và fan-out là hai khái niệm dễ nhầm vì nghe tương tự nhau nhưng đo hai chiều khác nhau: fan-out đo khả năng CUNG CẤP tải của một đầu ra, còn fan-in đo lượng tải mà một đầu vào ÁP LÊN nguồn tín hiệu đang điều khiển nó. Một đầu vào chuẩn của cùng họ logic luôn có fan-in bằng 1 theo định nghĩa.</p>', detail_en="<p>Fan-in and fan-out are easy to confuse because they sound similar but measure two different directions: fan-out measures an output's capacity to SUPPLY load, while fan-in measures how much load an input PLACES on the source driving it. A standard input of the same logic family always has a fan-in of 1 by definition.</p>"),
  dict(q="Tên gọi khác của bộ dồn kênh (multiplexer) là:", en="Another name for a multiplexer is:",
       opts=["bộ chọn dữ liệu (data selector)","bộ thu phát bus (bus transceiver)","thanh ghi dịch (shift register)"], correct=0, src="Tooley Ch.9 Q4",
       explain="Multiplexer thường được gọi là 'data selector' vì chức năng chọn 1 trong nhiều nguồn dữ liệu đưa ra 1 ngõ ra.", detail="<p>Cái tên 'data selector' mô tả đúng bản chất chức năng của multiplexer hơn cả cái tên gốc: mạch này không 'trộn' nhiều tín hiệu lại như từ multiplex đôi khi gợi ý, mà chỉ đơn thuần CHỌN đúng một trong nhiều nguồn dữ liệu đầu vào để đưa ra ngõ ra duy nhất, dựa theo mã nhị phân trên các đường chọn.</p>", detail_en="<p>The name 'data selector' actually describes a multiplexer's function more accurately than the word 'multiplex' itself might suggest: the circuit does not blend several signals together, it simply SELECTS exactly one of several input data sources to pass through to a single output, based on the binary code on its select lines.</p>"),
  dict(q="Một bộ dồn kênh 4-sang-1 (4-to-1 multiplexer) cần bao nhiêu đường chọn (select input)?", en="A four-to-one multiplexer has:",
       opts=["một đường chọn","hai đường chọn","bốn đường chọn"], correct=1, src="Tooley Ch.9 Q5",
       explain="Cần n đường chọn để phân biệt 2ⁿ kênh vào; với 4 kênh, n=2.", detail='<p>Công thức n=log₂(N) áp dụng cho mọi bộ dồn kênh: cần đủ số đường chọn để mã nhị phân của chúng có thể đánh số hết N kênh dữ liệu đầu vào. Với 4 kênh, cần 2 đường chọn vì 2²=4; với 8 kênh sẽ cần 3 đường vì 2³=8, và cứ thế tăng dần.</p>', detail_en='<p>The formula n=log₂(N) applies to every multiplexer: there must be enough select lines for their binary code to number all N input data channels. With 4 channels, 2 select lines are needed because 2²=4; with 8 channels, 3 lines are needed because 2³=8, and so on as the channel count grows.</p>'),
  dict(q="Một số bộ mã hoá (encoder) có thêm chân enable input/output để cho phép:", en="Additional enable inputs and outputs are provided in some encoders in order to permit:",
       opts=["đảo tín hiệu (inverting)","ghép tầng (cascading)","phát hiện lỗi (error detection)"], correct=1, src="Tooley Ch.9 Q8",
       explain="Chân enable cho phép nối tầng (cascade) nhiều IC encoder để mở rộng số đầu vào mã hoá.", detail="<p>Một IC encoder đơn lẻ chỉ mã hoá được một số lượng đầu vào cố định theo thiết kế của nó. Chân enable input/output cho phép ghép nhiều IC encoder lại với nhau theo tầng (cascade), trong đó tầng có mức ưu tiên thấp hơn chỉ được phép hoạt động khi tầng ưu tiên cao hơn báo hiệu 'không có đầu vào nào tích cực' qua chính chân enable output của nó.</p>", detail_en='<p>A single encoder IC can only encode a fixed number of inputs by design. The enable input/output pins allow several encoder ICs to be cascaded together, where a lower-priority stage is only allowed to operate once the higher-priority stage signals, through its own enable output, that none of its inputs are currently active.</p>'),
  dict(q="Mạch logic trong Hình A2.10 (2 đầu vào A,B qua các tầng đảo, kết hợp qua 4 cổng AND-đảo) là:", en="The logic circuit arrangement shown in Figure A2.10 is:",
       opts=["bộ mã hoá 2-sang-4 đường","bộ giải mã 2-sang-4 đường","bộ dồn kênh 2-sang-2 đường"], correct=1, src="Tooley Revision Paper 2 Q12", img="tooley_A2_10.png",
       explain="2 đầu vào chọn ra đúng 1 trong 4 đường ra (Y0-Y3): đúng cấu trúc bộ giải mã (decoder) 2-sang-4, dùng cổng NAND để tạo ngõ ra tích cực mức thấp."),
  dict(q="Thiết bị logic trong Hình A2.11 (IC 16 chân với chân EI, GS, EO, A0-A2, 8 đầu vào) là:", en="The logic device shown in Figure A2.11 is:",
       opts=["bộ mã hoá 4-sang-3 đường","bộ mã hoá 8-sang-3 đường","bộ dồn kênh 4-sang-8 đường"], correct=1, src="Tooley Revision Paper 2 Q14", img="tooley_A2_11.png",
       explain="Sơ đồ chân khớp chính xác với IC 74148: bộ mã hoá ưu tiên 8-sang-3 đường (8-to-3 priority encoder)."),
  dict(q="Các pin trên một IC đóng gói DIL được đánh số:", en="The pins on a DIL packaged integrated circuit are numbered:",
       opts=["theo chiều kim đồng hồ từ pin 1","theo chiều kim đồng hồ từ pin 14","ngược chiều kim đồng hồ từ pin 1"], correct=2, src="Tooley Revision Paper 2 Q20",
       explain="Quy ước chuẩn JEDEC: nhìn từ trên xuống, đánh số ngược chiều kim đồng hồ bắt đầu từ pin 1 (góc có khấc/chấm định vị)."),
  dict(q="Loại thiết bị bán dẫn nào dễ bị hư hại nhất do tĩnh điện?", en="Which one of the following classes of semiconductor device is most susceptible to static voltages:",
       opts=["vi xử lý VLSI","transistor lưỡng cực (BJT)","chỉnh lưu có điều khiển silicon (SCR)"], correct=0, src="Tooley Revision Paper 5 Q10",
       explain="Vi xử lý VLSI dùng công nghệ MOS với lớp oxit cực mỏng ở cổng transistor: cực kỳ nhạy với phóng tĩnh điện (ESD) hơn hẳn linh kiện lưỡng cực (BJT/SCR)."),
  dict(q="Mạch tích hợp trong Hình A2.28 (chip khắc 'GD75232', đóng gói dán bề mặt) sử dụng kiểu đóng gói:", en="What type of package is used for the integrated circuit shown in Figure A2.28?",
       opts=["Pin grid array (PGA)","Dual-in-line pack (DIP)","Small outline integrated circuit (SOIC)"], correct=2, src="Tooley Revision Paper 7 Q20", img="tooley_A2_28.png",
       explain="Chân dạng gull-wing dán bề mặt hai bên, kích thước nhỏ gọn: đặc trưng gói SOIC."),
  dict(q="Thiết bị trong Hình A2.30 (IC 16 chân, đầu vào D0-D7, đầu ra Y/W, chọn A-B-C) có chức năng:", en="Which one of the following gives the function of the device shown in Figure A2.30?",
       opts=["Bộ dồn kênh (Multiplexer)","Thanh ghi dịch (Shift register)","Bộ cộng 4-bit (Four-bit adder)"], correct=0, src="Tooley Revision Paper 8 Q17", img="tooley_A2_30.png",
       explain="8 đầu vào dữ liệu (D0-D7), 3 đường chọn (A,B,C), 1 đầu ra (Y) và đầu ra phụ đảo (W): đúng cấu trúc IC 74151, bộ dồn kênh 8-sang-1."),
  dict(q="Trong Hình A2.31 (bộ ADC dốc đơn: bộ so sánh nhận tín hiệu analog và sóng răng cưa, đầu ra điều khiển cổng AND+bộ đếm), chức năng của IC1 là:", en="Which one of the following gives the function of IC1 in Figure A2.31?",
       opts=["Bộ so sánh (Comparator)","Nguồn cấp (Power supply)","Bộ đổi cực tính (Polarity changer)"], correct=0, src="Tooley Revision Paper 8 Q20", img="tooley_A2_31.png",
       explain="IC1 là ký hiệu op-amp so sánh (comparator) giữa tín hiệu analog vào và sóng răng cưa từ ramp generator: cấu trúc kinh điển của ADC dốc đơn (single-slope ADC)."),
]

